const STORE='kdp-launch-assistant-v1',defaults=()=>({id:crypto.randomUUID(),title:'',subtitle:'',author:'Heath Tolley',language:'English',description:'',conceptNote:'',buyerValue:'',group:'Uncategorized',status:'Idea',rights:'I own the copyright',audience:'No',aiText:'Not reviewed',release:'Release for sale now',keywords:Array(7).fill(''),categories:Array(3).fill(''),trim:'',pageCount:'',price:'',interiorName:'',coverName:'',checks:{previewer:false},files:{}});let products=[];try{products=JSON.parse(localStorage.getItem(STORE)||'[]')}catch{}let p=products[0]||defaults(),step='details';const $=s=>document.querySelector(s),save=()=>localStorage.setItem(STORE,JSON.stringify(products)),esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const steps=['details','discover','print','files','review'];const labels={details:'Book details',discover:'Discoverability',print:'Print setup',files:'Files',review:'Review packet'};function setView(v){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v));document.querySelectorAll('header [data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='saved')renderProducts()}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=b.dataset.step;render()});function input(name,label,type='text',extra=''){return `<label>${label}<input data-field="${name}" type="${type}" value="${esc(p[name])}" ${extra}></label>`}function area(name,label){return `<label>${label}<textarea data-field="${name}">${esc(p[name])}</textarea></label>`}function select(name,label,opts){return `<label>${label}<select data-field="${name}">${opts.map(x=>`<option ${p[name]===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}function render(){const panel=$('#panel');$('#productHeading').textContent=p.title||'Prepare a KDP product';document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',b.dataset.step===step));if(step==='details')panel.innerHTML=`<h2>Book details</h2><div class="fields">${select('group','Idea collection',['Uncategorized','How-to-Draw','Christian Coloring','Other Coloring','High-Value Guide'])}${select('status','Development status',['Idea','Researching','Writing','Designing','Final draft','PDFs ready','Ready for KDP','Published'])}${input('title','Book title')}${input('subtitle','Subtitle')}${input('author','Author')}${select('language','Language',['English','Spanish','French','German'])}</div>${area('description','Amazon description')}${area('conceptNote','Concept and reader promise')}${area('buyerValue','Buyer value commitment')}${select('rights','Publishing rights',['I own the copyright','Public domain','Permission documented'])}${select('audience','Adult-only content',['No','Yes'])}${select('aiText','AI-generated text',['Not reviewed','Yes - entire work, extensively edited','Yes - some sections, extensively edited','No'])}${select('release','Release',['Release for sale now','Schedule release'])}`;if(step==='discover')panel.innerHTML=`<h2>Discoverability</h2><p>Draft metadata, then compare against current KDP fields and the actual book.</p><div class="fields">${p.keywords.map((v,i)=>`<label>Keyword ${i+1}<input data-keyword="${i}" value="${esc(v)}"></label>`).join('')}</div><h3>Categories to consider</h3>${p.categories.map((v,i)=>`<label>Category ${i+1}<input data-category="${i}" value="${esc(v)}" placeholder="Choose inside KDP"></label>`).join('')}<p class="warning">KDP category names, keyword rules, and availability can change. Use the live KDP selector and never enter misleading metadata.</p>`;if(step==='print')panel.innerHTML=`<h2>Print setup</h2><div class="fields">${input('trim','Trim size','text','placeholder="e.g., 8.5 × 11 in"')}${input('pageCount','Page count','number','min="1"')}${input('price','Planned list price','number','min="0" step="0.01"')}</div><label>Interior ink / paper notes<textarea data-field="interiorNotes">${esc(p.interiorNotes)}</textarea></label><label>Cover notes<textarea data-field="coverNotes">${esc(p.coverNotes)}</textarea></label><p class="warning">Confirm trim, bleed, paper, margins, spine, and price in the current KDP workflow for this format and marketplace.</p>`;if(step==='files')panel.innerHTML=`<h2>Files</h2><p>Choose the final files to check filenames here. This app stores names only; keep the actual print files in your own project folder.</p><div class="filebox"><label>Interior manuscript<input id="interiorFile" type="file" accept=".pdf,.doc,.docx"></label><span class="tag">${esc(p.interiorName||'No interior selected')}</span></div><div class="filebox"><label>Cover file<input id="coverFile" type="file" accept=".pdf,.jpg,.jpeg,.png,.tif,.tiff"></label><span class="tag">${esc(p.coverName||'No cover selected')}</span></div><label>Project folder or backup notes<textarea data-field="fileNotes">${esc(p.fileNotes)}</textarea></label><p class="warning">Selecting a file does not upload it or preserve its contents. Re-select it after reopening this page.</p>`;if(step==='review')panel.innerHTML=`<h2>Review packet</h2><p class="warning">Review all details and current KDP rules yourself. No publishing action will be taken.</p><table class="review">${[['Title',p.title],['Subtitle',p.subtitle],['Author',p.author],['Language',p.language],['Description',p.description],['Keywords',p.keywords.filter(Boolean).join(' · ')],['Categories',p.categories.filter(Boolean).join(' · ')],['Trim',p.trim],['Page count',p.pageCount],['Price',p.price],['Interior file',p.interiorName],['Cover file',p.coverName],['Rights',p.rights],['AI disclosure',p.aiText]].map(([a,b])=>`<tr><td><b>${a}</b></td><td>${esc(b)||'—'}</td></tr>`).join('')}</table><label><input type="checkbox" data-check="previewer" ${p.checks?.previewer?'checked':''}> KDP Previewer reviewed by me</label><button id="exportOne">Export product JSON</button>`;panel.querySelectorAll('[data-field]').forEach(el=>el.onchange=()=>{p[el.dataset.field]=el.value;renderReadiness();save()});panel.querySelectorAll('[data-keyword]').forEach(el=>el.onchange=()=>{p.keywords[+el.dataset.keyword]=el.value;renderReadiness();save()});panel.querySelectorAll('[data-category]').forEach(el=>el.onchange=()=>{p.categories[+el.dataset.category]=el.value;renderReadiness();save()});panel.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{p.checks[el.dataset.check]=el.checked;save();renderReadiness()});$('#interiorFile')?.addEventListener('change',e=>{p.interiorName=e.target.files[0]?.name||'';save();render()});$('#coverFile')?.addEventListener('change',e=>{p.coverName=e.target.files[0]?.name||'';save();render()});$('#exportOne')?.addEventListener('click',()=>download([p],'kdp-product.json'));renderReadiness()}const checklist=()=>[['Title entered',!!p.title],['Subtitle matches cover',!!p.subtitle],['Description completed',p.description.trim().length>0],['Seven keywords entered',p.keywords.filter(x=>x.trim()).length===7],['Three categories chosen',p.categories.filter(x=>x.trim()).length===3],['Page count confirmed',+p.pageCount>0],['Price selected',+p.price>0],['Interior file selected',!!p.interiorName],['Cover file selected',!!p.coverName],['AI disclosure reviewed',p.aiText!=='Not reviewed'],['Publishing rights reviewed',p.rights!==''],['KDP Previewer approved',!!p.checks?.previewer]];function renderReadiness(){const checks=checklist(),done=checks.filter(x=>x[1]).length;$('#percent').textContent=`${Math.round(done/checks.length*100)}% ready`;$('#fieldCount').textContent=`${done}/${checks.length} checks · ${+!!p.interiorName+ +!!p.coverName}/2 file names`;$('#checklist').innerHTML=checks.map(([l,ok])=>`<div class="check"><label><input type="checkbox" disabled ${ok?'checked':''}>${esc(l)}</label></div>`).join('')}function renderProducts(){$('#productList').innerHTML=products.length?products.map((x,i)=>`<div class="product"><span><b>${esc(x.title||'Untitled product')}</b><span class="tag"> · ${esc(x.status)}</span></span><span><button data-open="${i}">Open</button> <button data-delete="${i}">Delete</button></span></div>`).join(''):'No saved product records yet.';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{p=products[+b.dataset.open];step='details';setView('workspace');render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{products.splice(+b.dataset.delete,1);save();renderProducts()})}function download(obj,name){const a=document.createElement('a'),b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'});a.href=URL.createObjectURL(b);a.download=name;a.click();URL.revokeObjectURL(a.href)}$('#saveBtn').onclick=()=>{const i=products.findIndex(x=>x.id===p.id);if(i<0)products.unshift(p);else products[i]=p;save();$('#saveBtn').textContent='Saved ✓';setTimeout(()=>$('#saveBtn').textContent='Save product',1100)};$('#newBtn').onclick=()=>{p=defaults();step='details';render()};$('#importBtn').onclick=()=>$('#importDialog').showModal();$('#doImport').onclick=e=>{e.preventDefault();const f=$('#importFile').files[0];if(!f)return;f.text().then(t=>{const v=JSON.parse(t),arr=Array.isArray(v)?v:[v];for(const x of arr)if(x&&x.id&&typeof x==='object'&&!products.some(y=>y.id===x.id))products.push(x);save();p=arr[0]||defaults();$('#importDialog').close();setView('workspace');render()}).catch(()=>alert('Could not read that KDP JSON package.'))};$('#exportAll').onclick=()=>download(products,'kdp-products-backup.json');render();
